"""Windows 原语：进程句柄、进程树枚举、Job Object 与输出管道。

只使用标准库（``_winapi`` + ``ctypes``），不联网，也不依赖任何第三方库。

这里所有函数遵守同一条纪律：**失败时返回一个可用的退化值，而不是抛
异常**。监督子进程的逻辑绝不能因为单个系统调用失败就把异常抛给
``run()`` 的调用方。
"""

from __future__ import annotations

import ctypes
import sys

if sys.platform != "win32":  # pragma: no cover - 只在 Windows 上可用
    raise ImportError("wproc._win32 is Windows-only")

import _winapi
import msvcrt

__all__ = [
    "SYNCHRONIZE",
    "PROCESS_TERMINATE",
    "PROCESS_SET_QUOTA",
    "WAIT_OBJECT_0",
    "JobObject",
    "close_handle",
    "create_pipe",
    "descendant_pids",
    "fd_from_handle",
    "handle_alive",
    "open_process",
    "peek_pipe",
    "pipe_handle_of",
    "process_pairs",
    "read_pipe",
    "terminate_process",
    "wait_process",
]

# ---- 访问权限 / 等待状态 ----
SYNCHRONIZE = 0x00100000
PROCESS_TERMINATE = 0x0001
PROCESS_SET_QUOTA = 0x0100

WAIT_OBJECT_0 = 0x00000000

# ---- Toolhelp32 进程快照 ----
_TH32CS_SNAPPROCESS = 0x00000002

# ---- Job Object ----
_JOB_OBJECT_BASIC_PROCESS_ID_LIST = 3

_kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)

_kernel32.CreateToolhelp32Snapshot.restype = ctypes.c_void_p
_kernel32.CreateToolhelp32Snapshot.argtypes = [ctypes.c_ulong, ctypes.c_ulong]

_kernel32.CloseHandle.restype = ctypes.c_int
_kernel32.CloseHandle.argtypes = [ctypes.c_void_p]

_kernel32.CreateJobObjectW.restype = ctypes.c_void_p
_kernel32.CreateJobObjectW.argtypes = [ctypes.c_void_p, ctypes.c_wchar_p]

_kernel32.AssignProcessToJobObject.restype = ctypes.c_int
_kernel32.AssignProcessToJobObject.argtypes = [ctypes.c_void_p, ctypes.c_void_p]

_kernel32.TerminateJobObject.restype = ctypes.c_int
_kernel32.TerminateJobObject.argtypes = [ctypes.c_void_p, ctypes.c_uint]

_kernel32.QueryInformationJobObject.restype = ctypes.c_int
_kernel32.QueryInformationJobObject.argtypes = [
    ctypes.c_void_p,                    # hJob
    ctypes.c_int,                       # JobObjectInformationClass
    ctypes.c_void_p,                    # lpJobObjectInformation
    ctypes.c_ulong,                     # cbJobObjectInformationLength
    ctypes.POINTER(ctypes.c_ulong),     # lpReturnLength
]


# ---------------------------------------------------------------- 句柄与进程


def open_process(pid, access) -> "int | None":
    """按 PID 打开进程句柄；失败（含进程已退出）返回 ``None``。"""
    if pid is None:
        return None
    try:
        return _winapi.OpenProcess(int(access), False, int(pid))
    except OSError:
        return None


def close_handle(handle) -> None:
    """关闭一个 OS 句柄；失败时静默。"""
    if not handle:
        return
    try:
        _winapi.CloseHandle(handle)
    except OSError:
        pass


def wait_process(handle, milliseconds):
    """等待句柄变为有信号，返回 ``WAIT_OBJECT_0`` 或超时代码；失败返回 ``None``。"""
    if not handle:
        return WAIT_OBJECT_0
    try:
        return _winapi.WaitForSingleObject(handle, int(milliseconds))
    except OSError:
        return None


def handle_alive(handle) -> bool:
    """句柄对应的进程是否仍在运行（无法确定时按仍在运行处理）。"""
    if not handle:
        return False
    status = wait_process(handle, 0)
    return status is None or status != WAIT_OBJECT_0


def terminate_process(handle, exit_code: int = 1) -> bool:
    """通过句柄终止一个进程；返回是否成功。"""
    if not handle:
        return False
    try:
        _winapi.TerminateProcess(handle, int(exit_code))
        return True
    except OSError:
        return False


# ---------------------------------------------------------------- 输出管道


def create_pipe(size: int):
    """创建匿名管道，返回 ``(读端句柄, 写端句柄)``；失败返回 ``(None, None)``。"""
    try:
        read_handle, write_handle = _winapi.CreatePipe(None, int(size))
        return read_handle, write_handle
    except OSError:
        return None, None


def fd_from_handle(handle):
    """把 OS 句柄包装成 CRT 文件描述符；关闭该描述符会一并关闭句柄。"""
    if handle is None:
        return None
    try:
        return msvcrt.open_osfhandle(handle, 0)
    except OSError:
        return None


def pipe_handle_of(fd):
    """取文件描述符背后的 OS 句柄；失败返回 ``None``。"""
    if fd is None:
        return None
    try:
        return msvcrt.get_osfhandle(fd)
    except OSError:
        return None


def peek_pipe(handle) -> int:
    """管道中当前可读的字节数；管道已断开（再也不会有数据）返回 ``-1``。"""
    try:
        return int(_winapi.PeekNamedPipe(handle, 0)[0])
    except OSError:
        return -1


def read_pipe(handle, size: int):
    """从管道读至多 ``size`` 字节；调用前必须已确认管道里有数据。"""
    try:
        return _winapi.ReadFile(handle, int(size))[0]
    except OSError:
        return None


# -------------------------------------------------------------- 进程树枚举


class _ProcessEntry32W(ctypes.Structure):
    _fields_ = [
        ("dwSize", ctypes.c_ulong),
        ("cntUsage", ctypes.c_ulong),
        ("th32ProcessID", ctypes.c_ulong),
        ("th32DefaultHeapID", ctypes.c_size_t),
        ("th32ModuleID", ctypes.c_ulong),
        ("cntThreads", ctypes.c_ulong),
        ("th32ParentProcessID", ctypes.c_ulong),
        ("pcPriClassBase", ctypes.c_long),
        ("dwFlags", ctypes.c_ulong),
        ("szExeFile", ctypes.c_wchar * 260),
    ]


# CreateToolhelp32Snapshot 失败时的返回值（按 c_void_p 解释）。
_INVALID_SNAPSHOT = (None, 0, -1, 0xFFFFFFFFFFFFFFFF)


def process_pairs():
    """一次系统快照，返回 ``[(pid, ppid), ...]``；失败时返回空表。"""
    snapshot = _kernel32.CreateToolhelp32Snapshot(_TH32CS_SNAPPROCESS, 0)
    if snapshot in _INVALID_SNAPSHOT:
        return []
    try:
        entry = _ProcessEntry32W()
        entry.dwSize = ctypes.sizeof(_ProcessEntry32W)
        pairs = []
        ok = bool(_kernel32.Process32FirstW(snapshot, ctypes.byref(entry)))
        while ok:
            pairs.append((int(entry.th32ProcessID), int(entry.th32ParentProcessID)))
            ok = bool(_kernel32.Process32NextW(snapshot, ctypes.byref(entry)))
        return pairs
    except Exception:
        return []
    finally:
        _kernel32.CloseHandle(snapshot)


def descendant_pids(root_pid) -> "list[int]":
    """从 ``root_pid`` 出发按父子关系枚举它自己和全部后代。

    只做枚举、不做终止，调用方负责在根进程仍然存活时使用结果
    （根进程存活期间它的 PID 不会被复用，结果因此可信）。
    """
    pairs = process_pairs()
    children = {}
    for pid, ppid in pairs:
        children.setdefault(ppid, []).append(pid)
    order = []
    seen = set()
    stack = [int(root_pid)]
    while stack:
        pid = stack.pop()
        if pid in seen:
            continue
        seen.add(pid)
        order.append(pid)
        stack.extend(children.get(pid, ()))
    return order


# ---------------------------------------------------------------- Job Object


def _make_pid_list(capacity: int):
    class _PidList(ctypes.Structure):
        _fields_ = [
            ("NumberOfAssignedProcesses", ctypes.c_ulong),
            ("NumberOfProcessIdsInList", ctypes.c_ulong),
            ("ProcessIdList", ctypes.c_size_t * capacity),
        ]

    return _PidList()


class JobObject:
    """一个专属 Job Object。

    子进程挂进作业之后，它启动的所有后代都会自动落在同一个作业里，
    ``terminate()`` 一次就能结束整棵树——包括那些父进程已经死掉、
    按父子关系已经追不到的后代。
    """

    __slots__ = ("_handle",)

    def __init__(self) -> None:
        self._handle = None

    def create(self) -> bool:
        handle = _kernel32.CreateJobObjectW(None, None)
        if not handle:
            return False
        self._handle = handle
        return True

    def assign(self, process_handle) -> bool:
        if not self._handle or not process_handle:
            return False
        return bool(_kernel32.AssignProcessToJobObject(self._handle, process_handle))

    def terminate(self, exit_code: int = 1) -> bool:
        """终止作业里的所有进程。"""
        if not self._handle:
            return False
        return bool(_kernel32.TerminateJobObject(self._handle, int(exit_code)))

    def pids(self) -> "list[int]":
        """作业中当前进程的 PID 列表；失败返回空表。"""
        if not self._handle:
            return []
        capacity = 64
        for _ in range(4):
            buffer = _make_pid_list(capacity)
            needed = ctypes.c_ulong(0)
            ok = bool(
                _kernel32.QueryInformationJobObject(
                    self._handle,
                    _JOB_OBJECT_BASIC_PROCESS_ID_LIST,
                    ctypes.byref(buffer),
                    ctypes.sizeof(buffer),
                    ctypes.byref(needed),
                )
            )
            if ok:
                return [
                    int(buffer.ProcessIdList[index])
                    for index in range(buffer.NumberOfProcessIdsInList)
                ]
            capacity *= 16
        return []

    def close(self) -> None:
        """关闭作业句柄。作业里若有仍在运行的进程，它们不受影响。"""
        if self._handle:
            close_handle(self._handle)
            self._handle = None

"""子进程的启动与结束。

把「如何在 Windows 上创建并结束一个子进程」集中在一处，
让 runner 只关心预算、输出与结果封装。

这里集中处理三类真实的 Windows 现场问题：

1. **超时之后进程树还在跑**。子进程一启动就被挂进一个专属的
   Job Object，它拉起来的所有后代都会自动落进同一个作业。
   终止时先趁根进程还活着按父子关系快照后代，再终止整个作业，
   再对快照里的进程逐个补刀，最后等整棵树**真正退出**才返回，
   因此 ``run()`` 返回之后不会再有这次运行的进程继续活动。
   终止只作用于这次运行自己的进程（作业成员 + 可以按父子关系
   证明是其后代的进程），不会波及其它无关进程。
2. **超时之后输出不见了**。stdout 与 stderr 合并进一条容量充足
   （1 MiB）的管道，由监督循环持续收走；无论正常结束还是被终止，
   结束之前写进管道的内容都会进入结果，不会因为「到点了」被整段
   丢弃，也不会因为输出量大而丢失。
3. **明明结束了的命令被判成超时**。只把「直接子进程退出」当作
   这次运行结束：不等待它的后代释放输出管道；它一退出，管道里
   已有的内容照常收走，它留下的后台进程既不会被等待，也不会在
   正常结束时被终止。

非 Windows 平台上提供行为等价的退化实现（进程组 + ``select``），
语义与 Windows 一致。
"""

from __future__ import annotations

import io
import os
import select
import signal
import subprocess
import time
from typing import List, Mapping, Optional, Sequence

if os.name == "nt":
    from . import _win32
else:  # pragma: no cover - 非 Windows 的退化实现
    _win32 = None

Command = Sequence[str]

#: 输出管道的容量（字节）。子进程的大段输出先进管道，由监督循环收走。
PIPE_CAPACITY = 1 << 20

#: 单次从管道读取的上限（字节）。
READ_CHUNK = 1 << 16

#: 终止进程树时最多等待多久（秒）。
KILL_BUDGET = 5.0


def start_process(
    command: Command,
    cwd: Optional[str] = None,
    env: Optional[Mapping[str, str]] = None,
) -> subprocess.Popen:
    """启动一个子进程，把 stdout 与 stderr 合并到同一个管道里。"""
    argv = [str(item) for item in command]
    popen_env = dict(env) if env is not None else None
    if _win32 is not None:
        return _start_windows(argv, cwd, popen_env)
    return subprocess.Popen(
        argv,
        cwd=cwd,
        env=popen_env,
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        bufsize=0,
        start_new_session=True,
    )


def _start_windows(argv, cwd, popen_env) -> subprocess.Popen:
    """Windows：用自己的大容量管道承载合并后的输出。"""
    read_handle, write_handle = _win32.create_pipe(PIPE_CAPACITY)
    write_fd = _win32.fd_from_handle(write_handle) if write_handle else None
    if write_fd is None:
        if read_handle:
            _win32.close_handle(read_handle)
        if write_handle:
            _win32.close_handle(write_handle)
        # 拿不到自定义管道就退回标准管道（监督逻辑对两者一视同仁）
        return subprocess.Popen(
            argv,
            cwd=cwd,
            env=popen_env,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            bufsize=0,
        )

    try:
        proc = subprocess.Popen(
            argv,
            cwd=cwd,
            env=popen_env,
            stdin=subprocess.DEVNULL,
            stdout=write_fd,
            stderr=subprocess.STDOUT,
        )
    except BaseException:
        os.close(write_fd)  # 同时会关闭底层的写端句柄
        raise

    # 父进程必须立刻放掉写端，否则管道永远等不到 EOF
    os.close(write_fd)

    read_fd = _win32.fd_from_handle(read_handle)
    if read_fd is None:  # pragma: no cover - 几乎不可能发生
        _win32.close_handle(read_handle)
        return proc
    proc.stdout = io.open(read_fd, "rb", buffering=0)
    return proc


def terminate_process(proc: subprocess.Popen) -> None:
    """结束一个子进程，连同它启动的整棵进程树。

    调用返回后 ``proc`` 一定已经退出，``proc.returncode`` 可用。
    已经结束的进程不会被重复处理。
    """
    supervised = SupervisedChild(proc)
    try:
        if not supervised.poll_exited():
            supervised.kill_tree()
    finally:
        supervised.close(close_output=False)


class SupervisedChild:
    """监督一个已启动的子进程：等它结束、收它的输出、按需终止整棵树。

    只把「直接子进程退出」当作这次运行结束。它的后代既不会被等待，
    也不会在正常运行结束时被终止；只有因为超出时间预算而终止运行
    时，整棵进程树才会被结束。
    """

    def __init__(self, proc: subprocess.Popen) -> None:
        self.proc = proc
        self._chunks: List[bytes] = []
        self._broken = False  # 管道再也不会有新数据
        self._closed = False
        self._pipe_fd: Optional[int] = None
        self._pipe_handle = None
        self._child_handle = None  # 直接子进程的 OS 句柄（仅 Windows）
        self._job = None  # 专属 Job Object（仅 Windows）
        self._pgid: Optional[int] = None  # 直接子进程的进程组（仅 POSIX）
        self._setup()

    # ------------------------------------------------------------------ 设置

    def _setup(self) -> None:
        stdout = getattr(self.proc, "stdout", None)
        if stdout is not None:
            try:
                self._pipe_fd = stdout.fileno()
            except (OSError, ValueError):
                self._pipe_fd = None
        if self._pipe_fd is None:
            self._broken = True  # 没有输出管道可收

        if _win32 is not None:
            if self._pipe_fd is not None:
                self._pipe_handle = _win32.pipe_handle_of(self._pipe_fd)
            # 立刻打开直接子进程的句柄（拿到句柄之后就不再受 PID 复用
            # 影响），并尽快把它挂进专属 Job Object，让随后出生的所有
            # 后代都落进这个作业。
            self._child_handle = _win32.open_process(
                self.proc.pid,
                _win32.PROCESS_SET_QUOTA
                | _win32.PROCESS_TERMINATE
                | _win32.SYNCHRONIZE,
            )
            if self._child_handle is not None:
                job = _win32.JobObject()
                if job.create() and job.assign(self._child_handle):
                    self._job = job
                else:
                    job.close()
        else:
            # start_new_session=True：直接子进程自成一组，可整组终止
            self._pgid = self.proc.pid

    # -------------------------------------------------------------- 输出收集

    def drain(self) -> int:
        """把管道里当前已有的数据全部收走，返回本次收到的字节数。"""
        if self._broken:
            return 0
        if _win32 is not None:
            return self._drain_windows()
        return self._drain_posix()

    def _drain_windows(self) -> int:
        handle = self._pipe_handle
        if handle is None:
            return 0
        total = 0
        while True:
            available = _win32.peek_pipe(handle)
            if available < 0:
                self._broken = True  # 管道已断开：不会再有数据了
                break
            if available == 0:
                break
            data = _win32.read_pipe(handle, min(available, READ_CHUNK))
            if not data:
                self._broken = True
                break
            self._chunks.append(data)
            total += len(data)
        return total

    def _drain_posix(self) -> int:
        fd = self._pipe_fd
        if fd is None:
            return 0
        total = 0
        while True:
            try:
                ready, _, _ = select.select([fd], [], [], 0)
            except (OSError, ValueError):
                self._broken = True
                break
            if not ready:
                break
            try:
                data = os.read(fd, READ_CHUNK)
            except OSError:
                self._broken = True
                break
            if not data:
                self._broken = True  # EOF
                break
            self._chunks.append(data)
            total += len(data)
        return total

    def collect_final(self, idle: float = 0.03, cap: float = 1.0) -> None:
        """收尾：把管道里还能拿到的输出全部收走。

        - 管道断开（所有写端都关闭）后立即结束；
        - 连续 ``idle`` 秒没有新数据就结束——直接子进程一旦退出，
          它写过的内容必然已经在管道里，等下去只可能等到它后代的
          新输出；
        - 整个收尾最多 ``cap`` 秒，防止仍在运行的后代持续写导致
          收不完。
        """
        if self._broken:
            return
        started = time.monotonic()
        last_data = started
        while True:
            got = self.drain()
            now = time.monotonic()
            if got:
                last_data = now
            if self._broken:
                return
            if now - last_data >= idle or now - started >= cap:
                return
            time.sleep(0.002)

    def output(self) -> bytes:
        """已收集到的输出（合并后的 stdout 与 stderr）。"""
        if not self._chunks:
            return b""
        data = b"".join(self._chunks)
        self._chunks = [data]
        return data

    # ------------------------------------------------------------ 等待子进程

    def poll_exited(self) -> bool:
        """直接子进程是否已经退出。"""
        try:
            return self.proc.poll() is not None
        except Exception:
            return True

    def wait_slice(self, seconds: float) -> None:
        """最多等 ``seconds`` 秒让直接子进程退出。"""
        if seconds < 0:
            seconds = 0
        try:
            self.proc.wait(timeout=seconds)
        except subprocess.TimeoutExpired:
            pass
        except Exception:  # pragma: no cover - 兜底
            time.sleep(min(seconds, 0.05))

    def returncode(self) -> Optional[int]:
        """直接子进程的退出码；拿不到时为 ``None``。"""
        try:
            return self.proc.poll()
        except Exception:
            return None

    def _root_alive(self) -> bool:
        try:
            return self.proc.poll() is None
        except Exception:
            return False

    # ------------------------------------------------------------ 终止进程树

    def kill_tree(self, budget: float = KILL_BUDGET) -> None:
        """终止这次运行启动的整棵进程树，并等它们真正退出。

        只影响这次运行自己的进程：专属 Job Object 的成员，以及通过
        父子关系可以证明是其后代的进程。同一台机器上的其它进程不会
        被触碰。尽力而为，绝不抛异常。
        """
        try:
            if _win32 is not None:
                self._kill_tree_windows(budget)
            else:
                self._kill_tree_posix(budget)
        except Exception:
            # 终止失败也不允许把异常抛给调用方
            pass

    def _kill_tree_windows(self, budget: float) -> None:
        deadline = time.monotonic() + budget

        # 1) 趁直接子进程还活着，按父子关系快照它的后代。根进程存活
        #    期间它的 PID 不可能被复用，因此快照结果只属于这次运行。
        walked = []
        if self._root_alive():
            walked = _win32.descendant_pids(self.proc.pid)

        # 2) 先终止整个 Job：作业成员（包括挂进作业之后才出生、或者
        #    父进程已死而按父子关系追不到的后代）被原子地一并终止。
        if self._job is not None:
            self._job.terminate(1)

        # 3) 再对快照里的进程逐个补刀（覆盖挂进作业之前那一瞬间出生
        #    的漏网之鱼），并保留句柄用于等待。
        handles = {}
        for pid in walked:
            handle = _win32.open_process(
                pid, _win32.PROCESS_TERMINATE | _win32.SYNCHRONIZE
            )
            if handle is not None:
                handles[pid] = handle
                _win32.terminate_process(handle, 1)

        # 4) 等整棵树真正退出；仍有活动迹象就定期再补一刀。
        last_terminate = time.monotonic()
        while True:
            root_dead = not self._root_alive()
            walked_alive = [
                pid
                for pid, handle in handles.items()
                if _win32.handle_alive(handle)
            ]
            job_alive = self._job_alive_pids()
            if root_dead and not walked_alive and not job_alive:
                break
            now = time.monotonic()
            if now >= deadline:
                break
            if now - last_terminate >= 0.25:
                if self._job is not None:
                    self._job.terminate(1)
                for pid in walked_alive:
                    _win32.terminate_process(handles[pid], 1)
                last_terminate = now
            time.sleep(0.02)

        for handle in handles.values():
            _win32.close_handle(handle)

    def _job_alive_pids(self) -> List[int]:
        """Job 中仍未退出的进程 PID（只观察，绝不按 PID 终止）。"""
        if self._job is None:
            return []
        alive = []
        for pid in self._job.pids():
            handle = _win32.open_process(pid, _win32.SYNCHRONIZE)
            if handle is None:
                continue  # 打不开：进程多半已经彻底退出
            try:
                if _win32.handle_alive(handle):
                    alive.append(pid)
            finally:
                _win32.close_handle(handle)
        return alive

    def _kill_tree_posix(self, budget: float) -> None:
        deadline = time.monotonic() + budget
        if self._root_alive():
            if self._pgid is not None:
                try:
                    os.killpg(self._pgid, signal.SIGKILL)
                except OSError:
                    pass
            try:
                self.proc.kill()
            except Exception:
                pass
        while self._root_alive():
            try:
                self.proc.wait(timeout=0.1)
            except subprocess.TimeoutExpired:
                if time.monotonic() >= deadline:
                    try:
                        self.proc.kill()
                    except Exception:
                        pass
                    try:
                        self.proc.wait(timeout=0.5)
                    except Exception:
                        pass
                    break
            except Exception:
                break

    # ------------------------------------------------------------------ 收尾

    def close(self, close_output: bool = True) -> None:
        """释放监督所占的资源；不影响任何进程。"""
        if self._closed:
            return
        self._closed = True
        if close_output:
            stdout = getattr(self.proc, "stdout", None)
            if stdout is not None:
                try:
                    stdout.close()
                except Exception:
                    pass
        if self._child_handle is not None:
            _win32.close_handle(self._child_handle)
            self._child_handle = None
        if self._job is not None:
            self._job.close()
            self._job = None
